node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name).join(', '));
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get('ORD-5B048F');
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all('ORD-5B048F');
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

const fulfillments = db.prepare('SELECT * FROM order_fulfillments WHERE order_id = ?').all('ORD-5B048F');
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all('ORD-5B048F');
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

if (order) {
  const customer = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);
  console.log('\n=== CUSTOMER ===');
  console.log(JSON.stringify(customer, null, 2));
}
"
